#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int minimumTimeToInitialState(std::string word, int k) {
        int n = word.size();
        std::vector<int> z(n, 0);
        int l = 0, r = 0;
        for (int i = 1; i < n; ++i) {
            if (i <= r) z[i] = std::min(r - i + 1, z[i - l]);
            while (i + z[i] < n && word[z[i]] == word[i + z[i]]) z[i]++;
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        for (int t = 1; t * k < n; ++t) {
            if (z[t * k] >= n - t * k) return t;
        }
        return (n + k - 1) / k;
    }
};

class Solution {
    public int minimumTimeToInitialState(String word, int k) {
        int n = word.length();
        int[] z = new int[n];
        int l = 0, r = 0;
        for (int i = 1; i < n; ++i) {
            if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);
            while (i + z[i] < n && word.charAt(z[i]) == word.charAt(i + z[i])) z[i]++;
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        for (int t = 1; t * k < n; ++t) {
            if (z[t * k] >= n - t * k) return t;
        }
        return (n + k - 1) / k;
    }
}

var minimumTimeToInitialState = function(word, k) {
    const n = word.length;
    const z = new Array(n).fill(0);
    let l = 0, r = 0;
    for (let i = 1; i < n; ++i) {
        if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);
        while (i + z[i] < n && word[z[i]] === word[i + z[i]]) z[i]++;
        if (i + z[i] - 1 > r) {
            l = i;
            r = i + z[i] - 1;
        }
    }
    for (let t = 1; t * k < n; ++t) {
        if (z[t * k] >= n - t * k) return t;
    }
    return Math.floor((n + k - 1) / k);
};
